using HRM.DTOs;
using HRM.DTOs.Leadership;
using HRM.Models;
using HRM.Models.Leadership;
using HRM.Services.Contracts;
using HRM.Services.Interfaces;
using Microsoft.EntityFrameworkCore;
namespace HRM.Services;
public sealed partial class LeadershipAdministrationService(IDbContextFactory<HrmTeContext> factory,IUserAccessService access) : LeadershipAdministrationServiceContracts.IOperations
{
 private async Task<int> RequireAdministratorAsync(){var actor=await access.RequireContextAsync();if(!actor.IsSuperAdministrator&&!await access.HasPermissionAsync("Leadership.Appointment.Manage"))throw new UnauthorizedAccessException("Leadership appointment administration requires MDS superadmin or delegated HR permission.");return actor.UserId;}
 public async Task<ServiceResult> SaveAppointmentTypeAsync(LeadershipAppointmentTypeInput input,CancellationToken ct=default){await RequireAdministratorAsync();if(string.IsNullOrWhiteSpace(input.Name))return new ServiceResult(false,"Appointment type name is required.");await using var db=await factory.CreateDbContextAsync(ct);if(input.Name.Length>120||input.Description?.Length>500)return ServiceResult.Fail("Appointment type exceeds the allowed length.");if(await db.LeadershipAppointmentTypes.AnyAsync(x=>x.Name==input.Name.Trim()&&x.LeadershipAppointmentTypeId!=input.LeadershipAppointmentTypeId,ct))return ServiceResult.Fail("Appointment type already exists.");var type=input.LeadershipAppointmentTypeId==0?new LeadershipAppointmentType():await db.LeadershipAppointmentTypes.SingleOrDefaultAsync(x=>x.LeadershipAppointmentTypeId==input.LeadershipAppointmentTypeId,ct)??throw new KeyNotFoundException("Appointment type not found.");type.Name=input.Name.Trim();type.Description=input.Description?.Trim();type.IsActive=input.IsActive;if(input.LeadershipAppointmentTypeId==0)db.LeadershipAppointmentTypes.Add(type);await db.SaveChangesAsync(ct);return new ServiceResult(true,"Appointment type saved.");}
 public async Task<ServiceResult> SaveAppointmentAsync(LeadershipAppointmentInput input,CancellationToken ct=default){var userId=await RequireAdministratorAsync();if(input.IndividualId<=0||input.LeadershipAppointmentTypeId<=0||input.AppointingOrganisationId<=0||string.IsNullOrWhiteSpace(input.PositionTitle)||input.EffectiveFrom==default||input.EffectiveTo<input.EffectiveFrom)return new ServiceResult(false,"Appointment details are invalid.");await using var db=await factory.CreateDbContextAsync(ct);if(input.PositionTitle.Length>200||input.AppointmentReference?.Length>100||input.Status!="Active")return ServiceResult.Fail("Use a valid title and reference; revoke appointments from the records screen.");if(!await db.Individuals.AnyAsync(x=>x.BusinessEntityId==input.IndividualId,ct)||!await db.LeadershipAppointmentTypes.AnyAsync(x=>x.LeadershipAppointmentTypeId==input.LeadershipAppointmentTypeId&&x.IsActive,ct)||!await db.Organisations.AnyAsync(x=>x.BusinessEntityID==input.AppointingOrganisationId,ct)||(input.AdministrativeOrganisationId.HasValue&&!await db.Organisations.AnyAsync(x=>x.BusinessEntityID==input.AdministrativeOrganisationId,ct)))return ServiceResult.Fail("Select valid person, appointment type and organisations.");LeadershipAppointment appointment;if(input.LeadershipAppointmentId==0){appointment=new(){IndividualId=input.IndividualId,LeadershipAppointmentTypeId=input.LeadershipAppointmentTypeId,AppointingOrganisationId=input.AppointingOrganisationId,AdministrativeOrganisationId=input.AdministrativeOrganisationId,PositionTitle=input.PositionTitle.Trim(),EffectiveFrom=input.EffectiveFrom,EffectiveTo=input.EffectiveTo,Status=input.Status.Trim(),AppointmentReference=input.AppointmentReference?.Trim()};db.LeadershipAppointments.Add(appointment);}else{appointment=await db.LeadershipAppointments.SingleOrDefaultAsync(x=>x.LeadershipAppointmentId==input.LeadershipAppointmentId,ct)??throw new KeyNotFoundException("Appointment not found.");appointment.LeadershipAppointmentTypeId=input.LeadershipAppointmentTypeId;appointment.AppointingOrganisationId=input.AppointingOrganisationId;appointment.AdministrativeOrganisationId=input.AdministrativeOrganisationId;appointment.PositionTitle=input.PositionTitle.Trim();appointment.EffectiveFrom=input.EffectiveFrom;appointment.EffectiveTo=input.EffectiveTo;appointment.Status=input.Status.Trim();appointment.AppointmentReference=input.AppointmentReference?.Trim();}await db.SaveChangesAsync(ct);db.LeadershipAuditLogs.Add(new LeadershipAuditLog{LeadershipAppointmentId=appointment.LeadershipAppointmentId,Action=input.LeadershipAppointmentId==0?"Created":"Updated",PerformedByUserId=userId,TimestampUtc=DateTime.UtcNow,Detail="Appointment record changed by authorised administrator."});await db.SaveChangesAsync(ct);return new ServiceResult(true,"Appointment saved.");}
 public async Task<ServiceResult> AddResponsibilityAsync(LeadershipResponsibilityInput input,CancellationToken ct=default){var userId=await RequireAdministratorAsync();if(input.LeadershipAppointmentId<=0||input.OrganisationId<=0||string.IsNullOrWhiteSpace(input.RelationshipType)||input.EffectiveFrom==default||input.EffectiveTo<input.EffectiveFrom)return new ServiceResult(false,"Organisation responsibility is invalid.");await using var db=await factory.CreateDbContextAsync(ct);var appointment=await db.LeadershipAppointments.SingleOrDefaultAsync(x=>x.LeadershipAppointmentId==input.LeadershipAppointmentId,ct)??throw new KeyNotFoundException("Appointment not found.");db.LeadershipAppointmentOrganisations.Add(new LeadershipAppointmentOrganisation{LeadershipAppointmentId=appointment.LeadershipAppointmentId,OrganisationId=input.OrganisationId,RelationshipType=input.RelationshipType.Trim(),EffectiveFrom=input.EffectiveFrom,EffectiveTo=input.EffectiveTo});db.LeadershipAuditLogs.Add(new LeadershipAuditLog{LeadershipAppointmentId=appointment.LeadershipAppointmentId,Action="ResponsibilityAdded",OrganisationId=input.OrganisationId,PerformedByUserId=userId,TimestampUtc=DateTime.UtcNow,Detail="Organisation responsibility added."});await db.SaveChangesAsync(ct);return new ServiceResult(true,"Organisation responsibility saved.");}
 public async Task<ServiceResult> AddAuthorityGrantAsync(LeadershipAuthorityGrantInput input,CancellationToken ct=default){var userId=await RequireAdministratorAsync();if(input.LeadershipAppointmentOrganisationId<=0||string.IsNullOrWhiteSpace(input.PermissionCode)||input.PermissionCode.Contains('*')||input.ValidFrom==default||input.ValidTo<input.ValidFrom)return new ServiceResult(false,"Authority grant is invalid.");await using var db=await factory.CreateDbContextAsync(ct);if(input.PermissionCode.Length>120||input.ScopeType!="Organisation"||!string.IsNullOrWhiteSpace(input.Conditions)||!await db.Roles.AnyAsync(x=>x.RoleKey==input.PermissionCode.Trim(),ct))return ServiceResult.Fail("Select an existing organisation permission. Conditional grants are not supported.");var link=await db.LeadershipAppointmentOrganisations.SingleOrDefaultAsync(x=>x.LeadershipAppointmentOrganisationId==input.LeadershipAppointmentOrganisationId,ct)??throw new KeyNotFoundException("Appointment organisation responsibility not found.");var grant=new LeadershipAuthorityGrant{LeadershipAppointmentOrganisationId=link.LeadershipAppointmentOrganisationId,PermissionCode=input.PermissionCode.Trim(),ScopeType=input.ScopeType.Trim(),Conditions=input.Conditions?.Trim(),ValidFrom=input.ValidFrom,ValidTo=input.ValidTo,IsActive=input.IsActive};db.LeadershipAuthorityGrants.Add(grant);db.LeadershipAuditLogs.Add(new LeadershipAuditLog{LeadershipAppointmentId=link.LeadershipAppointmentId,Action="AuthorityGranted",PerformedByUserId=userId,TimestampUtc=DateTime.UtcNow,OrganisationId=link.OrganisationId,Detail=$"Granted {grant.PermissionCode}."});await db.SaveChangesAsync(ct);return new ServiceResult(true,"Authority grant saved.");}
 public async Task<ServiceResult> AddDelegationAsync(LeadershipDelegationInput input,CancellationToken ct=default){var userId=await RequireAdministratorAsync();if(input.FromLeadershipAppointmentId<=0||input.ToUserId<=0||input.OrganisationId<=0||string.IsNullOrWhiteSpace(input.PermissionScope)||input.PermissionScope.Contains('*')||input.ValidFrom==default||input.ValidTo<input.ValidFrom)return ServiceResult.Fail("Delegation is invalid.");await using var db=await factory.CreateDbContextAsync(ct);if(!await db.Users.AnyAsync(x=>x.UserId==input.ToUserId&&x.IsActive,ct))return ServiceResult.Fail("Select an active delegate.");if(!await (from o in db.LeadershipAppointmentOrganisations join g in db.LeadershipAuthorityGrants on o.LeadershipAppointmentOrganisationId equals g.LeadershipAppointmentOrganisationId where o.LeadershipAppointmentId==input.FromLeadershipAppointmentId&&o.OrganisationId==input.OrganisationId&&g.IsActive&&g.PermissionCode==input.PermissionScope&&g.ValidFrom<=input.ValidFrom&&(g.ValidTo==null||(input.ValidTo!=null&&g.ValidTo>=input.ValidTo)) select g.LeadershipAuthorityGrantId).AnyAsync(ct))return ServiceResult.Fail("Delegation must be covered by an existing permission grant for the full date range.");var appointment=await db.LeadershipAppointments.SingleOrDefaultAsync(x=>x.LeadershipAppointmentId==input.FromLeadershipAppointmentId,ct);if(appointment==null)return ServiceResult.Fail("Appointment not found.");var responsibility=await db.LeadershipAppointmentOrganisations.AnyAsync(x=>x.LeadershipAppointmentId==input.FromLeadershipAppointmentId&&x.OrganisationId==input.OrganisationId&&x.EffectiveFrom<=input.ValidFrom&&(!x.EffectiveTo.HasValue||x.EffectiveTo>=input.ValidFrom),ct);if(!responsibility)return ServiceResult.Fail("The appointment has no active responsibility for this organisation.");db.LeadershipDelegations.Add(new LeadershipDelegation{FromLeadershipAppointmentId=input.FromLeadershipAppointmentId,ToUserId=input.ToUserId,OrganisationId=input.OrganisationId,PermissionScope=input.PermissionScope.Trim(),ValidFrom=input.ValidFrom,ValidTo=input.ValidTo,IsActive=true});db.LeadershipAuditLogs.Add(new LeadershipAuditLog{LeadershipAppointmentId=appointment.LeadershipAppointmentId,OrganisationId=input.OrganisationId,Action="Delegated",PerformedByUserId=userId,TimestampUtc=DateTime.UtcNow,Detail=$"Delegated {input.PermissionScope.Trim()} to user {input.ToUserId}."});await db.SaveChangesAsync(ct);return ServiceResult.Ok("Delegation saved.");}
 public async Task<ServiceResult> SaveAttendancePolicyAsync(LeadershipAttendancePolicyInput input,CancellationToken ct=default){var userId=await RequireAdministratorAsync();if(input.LeadershipAppointmentId<=0||input.ManagingOrganisationId<=0||string.IsNullOrWhiteSpace(input.VerificationMode)||input.EffectiveFrom==default||input.EffectiveTo<input.EffectiveFrom)return ServiceResult.Fail("Attendance policy is invalid.");await using var db=await factory.CreateDbContextAsync(ct);if(input.VerificationMode!="Standard")return ServiceResult.Fail("Only Standard verification is supported.");var owner=await db.LeadershipAppointments.SingleOrDefaultAsync(x=>x.LeadershipAppointmentId==input.LeadershipAppointmentId,ct);if(owner==null||owner.AdministrativeOrganisationId!=input.ManagingOrganisationId)return ServiceResult.Fail("Attendance must be managed by the appointment's administrative organisation.");if(await db.LeadershipAttendancePolicies.AnyAsync(x=>x.LeadershipAppointmentId==input.LeadershipAppointmentId&&(!x.EffectiveTo.HasValue||x.EffectiveTo>=input.EffectiveFrom)&&(!input.EffectiveTo.HasValue||x.EffectiveFrom<=input.EffectiveTo),ct))return ServiceResult.Fail("An attendance policy already covers this date range.");if(!await db.LeadershipAppointments.AnyAsync(x=>x.LeadershipAppointmentId==input.LeadershipAppointmentId,ct))return ServiceResult.Fail("Appointment not found.");db.LeadershipAttendancePolicies.Add(new LeadershipAttendancePolicy{LeadershipAppointmentId=input.LeadershipAppointmentId,ManagingOrganisationId=input.ManagingOrganisationId,AttendanceRequired=input.AttendanceRequired,VerificationMode=input.VerificationMode.Trim(),EffectiveFrom=input.EffectiveFrom,EffectiveTo=input.EffectiveTo});db.LeadershipAuditLogs.Add(new LeadershipAuditLog{LeadershipAppointmentId=input.LeadershipAppointmentId,OrganisationId=input.ManagingOrganisationId,Action="AttendancePolicySaved",PerformedByUserId=userId,TimestampUtc=DateTime.UtcNow,Detail="Attendance policy saved."});await db.SaveChangesAsync(ct);return ServiceResult.Ok("Attendance policy saved.");}
}
